import{z as n,x as s,o as A,c as m,q as B,j as r,D as e,d as t,s as o,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"ROME / MEMIT","description":"","frontmatter":{"title":"ROME / MEMIT","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rome-memit.md","filePath":"llm/rome-memit.md","lastUpdated":1791413859000}'),p={name:"llm/rome-memit.md"};function d(M,E,T,D,h,F){const l=s("Mermaid");return A(),m("div",null,[E[2]||(E[2]=B('<h1 id="rome-memit" tabindex="-1">ROME / MEMIT <a class="header-anchor" href="#rome-memit" aria-label="Permalink to &quot;ROME / MEMIT&quot;">​</a></h1><div class="epigraph"><p>一条事实往往集中在中层 MLP 把主语映射到属性的位置；改那个键值，不必再跑一遍指令 SFT。</p><footer>—— Meng 等，Locating and Editing Factual Associations in GPT（NeurIPS 2022）；Mass-Editing Memory in a Transformer（ICLR 2023）</footer></div><p><a href="/llm/lora-intrinsic-rank">内在秩</a>说明任务适应常落在低维切空间。有时你不要「学会一种任务」，只要改一条关联：Eiffel Tower 在巴黎 → 在罗马。全参或 <a href="/llm/lora">LoRA</a> SFT 会把整份条件分布拖向示范，副作用是邻近事实与口吻一起漂。Meng、Bau、Belinkov 等人的 ROME 先定位后编辑；MEMIT 把同一套键值更新扩到批量事实。本课打开「改一处而不动其他」。不把知识注入的限度（<a href="/llm/knowledge-injection-limits">下一课</a>）写成编辑已成功。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>因果语言建模把事实散在权重与上下文里。用户却按「主语–关系–客体」来想：谁位于哪里。SFT 用自然语言句子教这条，损失沿全序列回传，许多层、许多 token 都动。能否找到一个模块，它以主语的表示为键、以客体为值，像可改写的记忆槽？</p><p>定位若失败，编辑就是在随机层加扰动，等于劣质微调。定位若成功，仍要约束：改巴黎→罗马时，埃菲尔铁塔的高度、法国的首都不应一起变成罗马的。这是局部性指标，不是指令遵循分数。</p><h3 id="中层-mlp-当关联存储器" tabindex="-1">中层 MLP 当关联存储器 <a class="header-anchor" href="#中层-mlp-当关联存储器" aria-label="Permalink to &quot;中层 MLP 当关联存储器&quot;">​</a></h3><p>ROME 用因果追踪：把干净运行与损坏运行的激活对换，看客体 token 的概率何时恢复。发现：在主语最后 token 的位置上，中层 MLP 贡献关键。将该 MLP 的下行投影看成线性关联记忆 \\(W\\)，\\(k\\) 来自主语表示，\\(v\\) 编码客体。编辑变成：解一个约束最小二乘，使 \\(Wk_{\\mathrm{new}}\\approx v_{\\mathrm{new}}\\)，并尽量保持其它已有键。</p><p><span class="marginnote">「因果追踪」可以类比排查电路：给输入加点噪声（损坏运行），然后逐个位置把「干净激活」换回去，看输出什么时候恢复正确——恢复的那一刻，那个位置就是关键元件。它不训练模型，只是一次系统性的换件定位实验。</span></p><p><span class="marginnote">MEMIT 对多层、多事实同时解约束，把残差分配到一段 MLP 层，避免单层 \\(W\\) 过载。批量不是循环调用 ROME 一千次而不管层间耦合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每条事实构造提示（「The Eiffel Tower is located in」），取主语末 token 在选定层的激活为 \\(k\\)，用优化得到目标 \\(v\\)（使模型在客体位置输出新客体）。ROME 更新单层 \\(W\\)；MEMIT 选一段中层，解联合目标。插入后用生成与闭卷探针检查：目标事实是否改写、释义提示是否泛化、无关事实是否保持。</p><p>这与 SFT 契约正交：不经过<a href="/llm/chat-template">chat template</a> 的助手轮，也可以在基座补全格式上编辑。若产品是对话模型，编辑应在对齐后的权重上做，并用对话提示回归，否则补全编辑与助手行为脱节。</p>',13)),(A(),r(i,null,{default:e(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%9B%A0%E6%9E%9C%E8%BF%BD%E8%B8%AA%E5%AE%9A%E4%BD%8D%22%5D%20--%3E%20K%5B%22%E4%B8%BB%E8%AF%AD%E9%94%AE%20k%22%5D%0A%20%20C%20--%3E%20V%5B%22%E7%9B%AE%E6%A0%87%E5%80%BC%20v%22%5D%0A%20%20K%20--%3E%20U%5B%22%E7%BA%A6%E6%9D%9F%E6%9B%B4%E6%96%B0%20MLP%20%E7%9A%84%20W%22%5D%0A%20%20V%20--%3E%20U%0A%20%20U%20--%3E%20T%5B%22%E7%9B%AE%E6%A0%87%E4%BA%8B%E5%AE%9E%20%2F%20%E9%82%BB%E8%BF%91%E4%BA%8B%E5%AE%9E%20%2F%20%E6%B5%81%E7%95%85%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"不要用指令数据「再训一遍」代替定位：那是回到全分布适应。编辑失败时先查层是否选对、键是否取在主语末 token，再查约束权重。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"MLP 的 \\(W_{\\mathrm{down}}\\) 把高维特征映回残差。若某列方向专门为某主语–属性服务，改 \\(W\\) 使该键指向新值，相当于改写记忆。注意力负责把主语信息送到那个位置；编辑不改注意力，假设路由仍把同一主语送到同一槽。因此对未见句式的泛化取决于键是否稳定：换一种说法若主语表示漂移，编辑不触发。这解释了为何 ROME 在释义上部分泛化、在反向提示（罗马的地标是什么）上常失败——反向是另一条键，下一课的限度。",-1)),E[6]||(E[6]=a("p",null,"为什么同一处编辑，换种问法就失灵？键的稳定性决定触发与否：",-1)),(A(),r(i,null,{default:e(()=>[o(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q1%5B%22%E5%8E%9F%E5%8F%A5%E5%BC%8F%EF%BC%9A%E5%9F%83%E8%8F%B2%E5%B0%94%E9%93%81%E5%A1%94%E4%BD%8D%E4%BA%8E%E2%80%A6%E2%80%A6%22%5D%20--%3E%20K1%5B%22%E4%B8%BB%E8%AF%AD%E6%9C%AB%20token%20%E8%A1%A8%E7%A4%BA%20%3D%20%E8%A2%AB%E6%94%B9%E7%9A%84%E9%94%AE%22%5D%0A%20%20Q2%5B%22%E9%87%8A%E4%B9%89%E5%8F%A5%E5%BC%8F%EF%BC%9A%E9%82%A3%E5%BA%A7%E5%B7%B4%E9%BB%8E%E9%93%81%E5%A1%94%E2%80%A6%E2%80%A6%22%5D%20--%3E%20K2%5B%22%E7%9B%B8%E8%BF%91%E4%BD%86%E4%B8%8D%E5%90%8C%E7%9A%84%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20Q3%5B%22%E5%8F%8D%E5%90%91%E6%8F%90%E7%A4%BA%EF%BC%9A%E7%BD%97%E9%A9%AC%E7%9A%84%E5%9C%B0%E6%A0%87%E6%98%AF%E2%80%A6%E2%80%A6%22%5D%20--%3E%20K3%5B%22%E5%8F%A6%E4%B8%80%E6%9D%A1%E9%94%AE%EF%BC%8C%E7%BC%96%E8%BE%91%E6%B2%A1%E7%A2%B0%E8%BF%87%22%5D%0A%20%20K1%20--%3E%20S%5B%22%E5%91%BD%E4%B8%AD%E5%B7%B2%E6%94%B9%E5%86%99%E7%9A%84%E6%A7%BD%EF%BC%9A%E8%BE%93%E5%87%BA%E7%BD%97%E9%A9%AC%22%5D%0A%20%20K2%20--%3E%7C%22%E8%A1%A8%E7%A4%BA%E6%BC%82%E7%A7%BB%E5%B0%8F%22%7C%20S%0A%20%20K2%20--%3E%7C%22%E8%A1%A8%E7%A4%BA%E6%BC%82%E7%A7%BB%E5%A4%A7%22%7C%20M%5B%22%E4%B8%8D%E8%A7%A6%E5%8F%91%EF%BC%9A%E4%BB%8D%E8%BE%93%E5%87%BA%E5%B7%B4%E9%BB%8E%22%5D%0A%20%20K3%20--%3E%20M%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=B('<p><span class="marginnote">数字感受一下「局部」的含义：以 ROME 常用的 GPT-J（\\(d=4096\\)，FFN 中间维 \\(4d=16384\\)）为例，MLP 下投影 \\(W\\) 约 \\(4096 \\times 16384 \\approx 6710\\) 万个参数，而秩一更新只注入约 \\(5d = 20480\\) 个数（值向量 \\(4096\\) 维加键向量 \\(16384\\) 维）——约参数量的万分之三。这就是「改一个词条而不重印整本词典」的几何版本。</span></p><p>MEMIT 把 \\(\\|Wk-v\\|\\) 的残差分到多层，每层改得少，对无关键的破坏小于单层猛改。事实数量超过层容量时，仍会互相覆盖：局部编辑不是无限字典。</p><p><span class="marginnote">与 LoRA 的关系：可以在同一 MLP 上挂 LoRA 去做「可逆编辑」，但几何不同。ROME 直接改已有记忆槽；LoRA 在残差上加一段任务增量。批量事实用 MEMIT 通常比用一个事实表做 LoRA 更局部。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>编辑的是补全型事实探针，不是世界模型。涉及多跳、时间、计数的「事实」常常没有单一槽。安全对齐过的模型上，编辑可能被拒答头盖住：补全显示已改，对话仍拒绝或仍说旧答案。评测协议必须同时含补全与对话。规模上，MEMIT 能到数千条量级（论文设定），不是整部维基。超出则应用检索或接受微调的全局性。</p><p><span class="marginnote">常见误区：把 ROME/MEMIT 当成「更新知识库里的一个条目」。初学者容易以为改完「巴黎」后问「有什么好参观的」也会对——实际上编辑只重写了从主语表示出发的那条键值通路，推理链、反向查询、多跳组合走的是别的通路，不会自动跟着变。</span></p><p>下一课：即使槽改对了，把新知识当训练数据灌进去仍会幻觉——编辑成功 ≠ 注入成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ROME 用因果追踪把事实定位到主语位置的中层 MLP，再约束更新键值。</li><li>MEMIT 将批量更新分配到多层，减轻单层过载。</li><li>评测要含目标改写、释义泛化、无关事实与流畅度。</li><li>反向提示与多跳常不共享同一键，编辑不自动对称。</li><li>对话对齐模型须在助手提示上回归，不能只看补全。</li><li>出处：Meng 等，ROME，NeurIPS 2022；Meng 等，MEMIT，ICLR 2023。</li></ul>',9))])}const u=n(p,[["render",d]]);export{f as __pageData,u as default};
